observation.command:
curl -s "http://localhost:8080/supabase-events" 2>/dev/null | node -e "
const data = JSON.parse(require('fs').readFileSync(0, 'utf-8'));
console.log('Total events:', data.count);
console.log('Source counts:', JSON.stringify(data.source_counts, null, 2));
console.log('Active sources:', data.sources?.map(s => s.key).join(', '));
console.log('\nKulturhuset events:', data.events?.filter(e => e.source === 'kulturhuset').length || 0);
console.log('\nSample Kulturhuset events:');
data.events?.filter(e => e.source === 'kulturhuset').slice(0, 3).forEach(e => console.log('  -', e.title, '(' + e.date + ')'));
"
